/*==================================================
src/App.js

This is the top-level component of the app.
It contains the top-level state.
==================================================*/
import React, { Component } from 'react';
import { BrowserRouter as Router, Route } from 'react-router-dom';
import './App.css';
import Navbar from './components/Navbar';

// for api
import axios from 'axios';

// Import other components
import Home from './components/Home';
import UserProfile from './components/UserProfile';
import LogIn from './components/Login';
import Credits from './components/Credits';
import Debits from './components/Debits';

class App extends Component {
  constructor() {  // Create and initialize state
    super();
    this.state = {
      accountBalance: 1234567.89,
      creditList: [],
      debitList: [],
      currentUser: {
        userName: 'Joe Smith',
        memberSince: '11/22/99',
      }
    };
  }

  // from ApiDataComponent example
  async componentDidMount() {
    let creditURL = 'https://johnnylaicode.github.io/api/credits.json';
    let debitURL = 'https://johnnylaicode.github.io/api/debits.json';


    // Await for promise (completion) returned from API call
    try {
      let creditResponse = await axios.get(creditURL);
      let debitResponse = await axios.get(debitURL);

      const credits = creditResponse.data;
      const debits = debitResponse.data;

      // calc balance from API data
      const totalCredits = credits.reduce((sum, c) => sum + c.amount, 0);
      const totalDebits = debits.reduce((sum, d) => sum + d.amount, 0);
      const newBalance = totalCredits - totalDebits;

      // update states
      this.setState({
        creditList: creditResponse.data,
        debitList: debitResponse.data,
        accountBalance: newBalance,
      });

    }
    catch (error) {  // Print out errors at console when there is an error response
      if (error.response) {
        // The request was made, and the server responded with error message and status code.
        console.log(error.response.data);  // Print out error message (e.g., Not Found)
        console.log(error.response.status);  // Print out error status code (e.g., 404)
      }
    }
  }

  // Update state's currentUser (userName) after "Log In" button is clicked
  mockLogIn = (logInInfo) => {
    const newUser = { ...this.state.currentUser };
    newUser.userName = logInInfo.userName;
    this.setState({ currentUser: newUser })
  }

  addCredit = (desc, amount) => {
    const newCredit = {
      description: desc,
      amount: parseFloat(amount),
      date: new Date().toISOString(),
    };
    const updatedCredits = [...this.state.creditList, newCredit];
    const newBalance = this.state.accountBalance + newCredit.amount;
    this.setState({
      creditList: updatedCredits,
      accountBalance: newBalance,
    });
  }

  addDebit = (desc, amount) => {
    const newDebit = {
      description: desc,
      amount: parseFloat(amount),
      date: new Date().toISOString(),
    };
    const updatedDebits = [...this.state.debitList, newDebit];
    const newBalance = this.state.accountBalance - newDebit.amount;
    this.setState({
      debitList: updatedDebits,
      accountBalance: newBalance,
    });
  }

  // Create Routes and React elements to be rendered using React components
  render() {
    // Create React elements and pass input props to components
    const HomeComponent = () => (<Home accountBalance={this.state.accountBalance} />)
    const UserProfileComponent = () => (
      <UserProfile userName={this.state.currentUser.userName} memberSince={this.state.currentUser.memberSince} />
    )
    const LogInComponent = () => (<LogIn user={this.state.currentUser} mockLogIn={this.mockLogIn} />)
    const CreditsComponent = () => (
      <Credits
        credits={this.state.creditList}
        addCredit={this.addCredit}
        accountBalance={this.state.accountBalance}
      />)
    const DebitsComponent = () => (
      <Debits
        debits={this.state.debitList}
        addDebit={this.addDebit}
        accountBalance={this.state.accountBalance}
      />)

    // Important: Include the "basename" in Router, which is needed for deploying the React app to GitHub Pages
    return (
      <Router basename="/bank-of-react">
        <div className="App">
          <Navbar />
          <Route exact path="/" render={HomeComponent} />
          <Route exact path="/userProfile" render={UserProfileComponent} />
          <Route exact path="/login" render={LogInComponent} />
          <Route exact path="/credits" render={CreditsComponent} />
          <Route exact path="/debits" render={DebitsComponent} />
        </div>
      </Router>
    );
  }
}

export default App;